/**
 * Franky's own job photos. Raw data (sizes, blur placeholders) is generated by
 * scripts/process-photos.py into work.generated.ts; this file adds the curation.
 */
import { workPhotos } from "./work.generated";

export type WorkCategory = "showers" | "bathrooms" | "pipework" | "water" | "team";

export type WorkPhoto = {
  slug: string;
  src: string;
  width: number;
  height: number;
  category: WorkCategory;
  title: string;
  alt: string;
  blur: string;
  /** CSS object-position focal point for tight crops (cards, tiles). */
  focus?: string;
};

export type WorkVideo = {
  kind: "video";
  slug: string;
  src: string;
  poster: string;
  width: number;
  height: number;
  category: WorkCategory;
  title: string;
  alt: string;
};

export type GalleryItem = (WorkPhoto & { kind: "photo" }) | WorkVideo;

export const categories: { id: WorkCategory | "all"; label: string }[] = [
  { id: "all", label: "All work" },
  { id: "showers", label: "Showers" },
  { id: "bathrooms", label: "Bathrooms" },
  { id: "pipework", label: "Drainage & pipework" },
  { id: "water", label: "Hot water & pumps" },
  { id: "team", label: "Team at work" },
];

/** Focal points so portrait shots survive landscape/square crops. */
const focus: Record<string, string> = {
  "solar-geyser": "center 18%",
  "site-first-fix": "center 18%",
  "toilet-levelled": "center 22%",
  "team-shower-install": "center 45%",
  "team-drainage-trench": "center 40%",
  "borehole-pump": "center 70%",
  "drainage-inspection": "center 35%",
  "shower-double-door": "center 45%",
  "team-basin": "center 55%",
  "bath-rain-shower": "center 60%",
};

const withFocus = (p: Omit<WorkPhoto, "focus">): WorkPhoto => ({ ...p, focus: focus[p.slug] });

export function photo(slug: string): WorkPhoto {
  const p = workPhotos.find((w) => w.slug === slug);
  if (!p) throw new Error(`Unknown work photo: ${slug}`);
  return withFocus(p);
}

export const bathroomTour: WorkVideo = {
  kind: "video",
  slug: "bathroom-tour",
  src: "/video/bathroom-tour.mp4",
  poster: "/video/bathroom-tour-poster.webp",
  width: 576,
  height: 1024,
  category: "bathrooms",
  title: "Marble bathroom: video tour",
  alt: "Walkthrough of a finished marble bathroom: toilet, vanity and freestanding bath",
};

const asItem = (p: WorkPhoto): GalleryItem => ({ ...p, kind: "photo" });

/** Full gallery: curated order, video tour placed near the top. */
export const allWork: GalleryItem[] = (() => {
  const items = workPhotos.map((p) => asItem(withFocus(p)));
  items.splice(2, 0, bathroomTour);
  return items;
})();

/** Strongest shots for the home page (7 tiles + 1 wide = two full rows of 4). */
export const homeWork: GalleryItem[] = [
  "shower-smoked-glass", "team-shower-install", "bath-rain-shower", "solar-geyser",
  "shower-double-door", "team-drainage-trench", "freestanding-bath",
].map((s) => asItem(photo(s)));

export { workPhotos };
